+void
+unref_fd_head(gpointer data)
+{
+	fragment_head *fd_head = (fragment_head *) data;
+	fd_head->ref_count--;
+
+	if (fd_head->ref_count == 0) {
+		free_fd_head(fd_head);
+	}
+}
